  "settings.modelProvider.fieldHelp": "{field} 정보",
  "settings.modelProvider.help.contextWindow": "모델이 한 번에 처리할 수 있는 컨텍스트 용량. 토큰 단위. ZAICODE가 이를 사용해 컨텍스트를 관리합니다.\n모델의 실제 한도를 초과하지 마세요.",
  "settings.modelProvider.help.maxOutputTokens": "단일 모델 요청이 생성할 수 있는 최대 토큰 수.\n모델의 실제 한도를 초과하지 마세요.",
  "settings.modelProvider.help.inputModalities": "모델이 받을 수 있는 콘텐츠 유형을 설정합니다:\n\n- **텍스트**: 텍스트 콘텐츠를 받음. 필수.\n- **이미지**: 이미지 콘텐츠를 받음.\n- **비디오**: 비디오 콘텐츠를 받음.\n- **PDF**: PDF 문서를 직접 받음.",
  "settings.modelProvider.help.outputModalities": "모델 응답의 콘텐츠 유형. 현재는 텍스트만 지원합니다.",
  "settings.modelProvider.help.capabilities": "- **구조화 출력**: 출력 필드, 타입, 구조에 대한 JSON Schema 제약 지원.\n- **네이티브 웹 검색**: 모델 API의 내장 웹 검색 기능 지원.\n- **대화 중 시스템 메시지**: 대화 중 시스템 지시 삽입 지원.\n\n모델이 지원하지 않는 기능을 켜지 마세요.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "채팅에서 사용할 수 있는 추론 수준을 설정합니다. **낮은 추론 강도부터 높은 순서로 정렬해야 합니다**.\n모델이 지원하지 않는 추론 수준을 설정하지 마세요.",
  "settings.modelProvider.help.reasoningLevelMapping": "CEL 표현식으로 현재 추론 수준인 `reasoningLevel`을 모델 API 요청 필드에 매핑합니다. 표현식이 반환한 JSON 객체는 나가는 요청 본문과 병합됩니다.",
  "settings.modelProvider.help.advanced": "**MFJS 도구 스키마**: Moonshot Flavored JSON Schema 호환성 활성화. Moonshot의 Kimi 모델 API에서 주로 사용됩니다. 모델 API가 이 형식을 요구할 때만 켜세요.",
  "settings.modelProvider.help.followRecommendedConfig": "모델 ID, Base URL, API 형식을 사용해 권장 설정과 일치합니다. ZAICODE는 권장 사항을 계속 업데이트하고 자동으로 동기화합니다.\n설정을 직접 변경하면 해당 항목은 수동 관리로 전환되어 권장 업데이트를 따르지 않습니다. 나머지 설정은 스마트 설정이 계속 관리합니다.",
