  "zaicode.help.what": "ZAICODE는 당신의 에이전트 팀과 하위 에이전트 부대입니다. 에이전트가 작업 수행 -> 작업 대기열이 배정 -> 결과가 세션으로 스트리밍.",
  "zaicode.help.step1": "1. 에이전트 & 모드(왼쪽): Hunter, Tester, Cleaner, Wikier, Translator 및 사용자 지정 역할. 모드를 클릭해 활성화한 뒤 대기열에서 작업을 배정하면 에이전트가 투입됩니다.",
  "zaicode.help.step2": "2. 대기열(가운데): 새 작업 -> 작업 내용 입력 -> 에이전트 선택 -> 추가. 자동 운항을 켜면 자동으로 시작합니다.",
  "zaicode.help.step3": "3. 세부 정보(오른쪽): 작업을 클릭하면 상태·오류·결과를 보고 채팅 세션을 열 수 있습니다. 병렬 N은 동시 실행 작업 수입니다.",
  "zaicode.help.pools": "풀: SAIRoute는 9router 제공자입니다. SAIFREN = 무료 인터넷 모델, SAIOPP = 유료 심층 추론 모델.",
